//! Phase C second review: valid code that `#[composable]` fails to compile.
//!
//! A composable generated by a `macro_rules!` that takes the caller's body. A format capture
//! in a lambda (`"{n}"`) gets a key `Ident::new("n", Span::call_site())`, with the hygiene of
//! the `#[composable]` attribute (the macro's), not of the string literal (the caller's), so
//! it can't see the body's `n`: E0425 "cannot find value `n` in this scope", reported at the
//! macro. With an `n` in the macro, it keys the wrong local and keeps a stale closure
//! (review_c2::a_format_capture_keys_the_local_the_format_string_names). The key should take
//! the literal's span.
//!
//! Expected: compiles. Actual: E0425.

#![allow(non_snake_case, dead_code)]

use compose::runtime::*;

macro_rules! screen {
    ($name:ident ($($params:tt)*) $body:block) => {
        #[composable]
        fn $name($($params)*) $body
    };
}

#[composable]
fn Child(show: impl Fn() -> String + 'static) {
    let _ = show();
}

screen!(Wrapped(v: u32) {
    let n = v + 1;
    Child!(move || format!("{n}"));
});

#[test]
fn compiles() {}
